import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Cross-repository audit — 2026-09-04","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Cross-repository audit — 2026-09-04 | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/docs/CROSS-REPO-AUDIT.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Cross-repository audit — 2026-09-04 | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/docs/CROSS-REPO-AUDIT.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/docs/CROSS-REPO-AUDIT.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/docs/CROSS-REPO-AUDIT.html"}]]},"headers":[],"relativePath":"docs/CROSS-REPO-AUDIT.md","filePath":"docs/CROSS-REPO-AUDIT.md"}`),a={name:`docs/CROSS-REPO-AUDIT.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="cross-repository-audit-—-2026-09-04" tabindex="-1">Cross-repository audit — 2026-09-04 <a class="header-anchor" href="#cross-repository-audit-—-2026-09-04" aria-label="Permalink to “Cross-repository audit — 2026-09-04”">​</a></h1><p>Findings this repository computed about the other five, and the findings they returned. Recorded here because they were measured with this project&#39;s resources and existed only in inter-session messages.</p><p>The rule applied to every ledger, reproducible by any of them: address a claim by its statement text — collapse whitespace runs, remove a space only where it does not sit between two of <code>[A-Za-z0-9_]</code>, keep case, <code>==</code>→<code>=</code>, <code>!=</code>→<code>≠</code>, then <code>toUuid</code>. Run it with <code>npm run unique</code>.</p><h2 id="what-we-found-in-theirs" tabindex="-1">What we found in theirs <a class="header-anchor" href="#what-we-found-in-theirs" aria-label="Permalink to “What we found in theirs”">​</a></h2><table tabindex="0"><thead><tr><th>repo</th><th>claims</th><th>distinct</th><th>repeated</th><th>what the repeats were</th></tr></thead><tbody><tr><td>erpax</td><td>2899</td><td>2894</td><td>5</td><td>four are ONE boilerplate sentence across five <code>SKILL.md</code> files</td></tr><tr><td>ceccec.github.io</td><td>832</td><td>831</td><td>1</td><td><code>golden_ratio_bounds</code> proved in two Lean files — a duplicate result</td></tr><tr><td>zeropoint-node</td><td>142</td><td>141</td><td>1</td><td>a markdown <code>##</code> heading extracted as a claim</td></tr><tr><td>uuidna</td><td>2548</td><td>2548</td><td>0</td><td>the only ledger of six with none</td></tr><tr><td>aequator</td><td>21</td><td>21</td><td>0</td><td>—</td></tr><tr><td><strong>millennium-solutions</strong></td><td>534</td><td>528</td><td><strong>6</strong></td><td>three genuine pairs, three the address&#39;s own limit</td></tr></tbody></table><p>Across all six: <strong>6442 sibling claims scanned, zero share a statement address with ours.</strong> No duplicate publication exists at the statement level. Weak evidence, and said so: several of those ledgers hold prose where ours holds Lean, so the scan cannot see two repositories stating one fact differently.</p><h2 id="what-they-found-in-ours" tabindex="-1">What they found in ours <a class="header-anchor" href="#what-they-found-in-ours" aria-label="Permalink to “What they found in ours”">​</a></h2><ul><li><strong>uuidna-49</strong> attacked our statement-address spec at our request and it was wrong on 74% of this tree. Stripping all whitespace breaks Lean&#39;s application by juxtaposition — <code>List.range 7</code> became <code>list.range7</code>, and <code>rawBytes A</code> became <code>rawbytesa</code>; 395 of 534 statements carry such a space and 333 carry an uppercase identifier that lowercasing destroyed. Their amendment is adopted verbatim.</li><li><strong>uuidna-49</strong> also carried the reverse of our DOI defect: they had declared <code>21787144</code> — the Clay-proofs paper — as uuidna&#39;s own standing archive, in seven places.</li><li><strong>ceccec.github.io</strong> found our lineage gate read only TITLES, and harvested <code>21787144</code>&#39;s description: <em>&quot;Complete quantum proofs of all 6 Clay Millennium Problems … machine-checked.&quot;</em></li><li><strong>zeropoint-node</strong> named the shape of a record written into a directory the same script fingerprints. Checked here: three such sites, all three already safe, none of it held by anything until now.</li></ul><h2 id="the-finding-neither-side-was-looking-for" tabindex="-1">The finding neither side was looking for <a class="header-anchor" href="#the-finding-neither-side-was-looking-for" aria-label="Permalink to “The finding neither side was looking for”">​</a></h2><p><code>10.5281/zenodo.21787143</code> is a Zenodo <strong>concept DOI</strong> and resolves to the latest version of its chain. Three unrelated works are in that chain:</p><table tabindex="0"><thead><tr><th>version</th><th>title</th></tr></thead><tbody><tr><td>21787144</td><td>Quantum Proofs of the Clay Millennium Problems v1.0</td></tr><tr><td>21819217</td><td>Millennium Solutions — The ℤ/9 Vortex Framework (what this repo cites)</td></tr><tr><td>22256708</td><td>uuidna — content-addressed identity (what the concept resolves to now)</td></tr></tbody></table><p>So a citation of the concept for millennium-solutions is handed uuidna, and a new version published under that concept to correct the Clay-proofs record would supersede uuidna&#39;s deposit instead. Reported to both.</p><p><strong>A concept DOI has no OAI record</strong> — <code>GetRecord</code> returns <code>idDoesNotExist</code> — so it can only be followed by HTTP resolution. A harvester reports a false absence for exactly the identifier most likely to be wrong.</p><p>Run <code>npm run doi-resolve</code> and <code>npm run lineage</code> to recheck all of it.</p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};